def lookup_ddc(code: str) -> Optional[DdcDivision]:
    """Look up DDC division by 3-digit code."""
    return DDC_DIVISIONS.get(code.strip()[:3])

def get_divisions_for_class(main_class: str) -> List[DdcDivision]:
    """Get all divisions belonging to a main class (e.g. 000, 500, 600)."""
    return [div for div in DDC_DIVISIONS.values() if div.main_class == main_class]
